@RestController
@RequestMapping("/api/cart")
public class ShoppingCartController {

    private final ShoppingCart shoppingCart;

    // Constructor injection of a Session-scoped bean utilizing a scoped proxy
    public ShoppingCartController(ShoppingCart shoppingCart) {
        this.shoppingCart = shoppingCart;
    }

    @PostMapping("/item")
    public ResponseEntity<String> addItem(@RequestBody Item item) {
        shoppingCart.addItem(item);
        return ResponseEntity.ok("Item added to session-scoped cart");
    }
}

@Component
@Scope(value = WebApplicationContext.SCOPE_SESSION, proxyMode = ScopedMode.TARGET_CLASS)
class ShoppingCart {
    private final List<Item> items = new ArrayList<>();

    public void addItem(Item item) {
        this.items.add(item);
    }

    public List<Item> getItems() {
        return Collections.unmodifiableList(items);
    }
}
